"""Embedded, offline presentation assets for the evidence workspace."""
STYLE = r'''
:root{color-scheme:light dark;--bg:#f4f7f8;--paper:#fff;--ink:#203238;--soft:#61767c;--line:#dde6e7;--accent:#136f68;--active:#e1f1ec;font:14px/1.5 system-ui,sans-serif;color:var(--ink);background:var(--bg)}
*{box-sizing:border-box}body{margin:0}header{padding:24px 32px;display:flex;gap:20px;align-items:center;background:var(--paper);border-bottom:1px solid var(--line)}header pre{font:bold 17px/1.1 monospace;color:var(--accent);background:none;padding:0;margin:0}h1{font-size:22px;margin:0}h2{font-size:22px;margin:0 0 12px}small,footer{color:var(--soft)}.workspace{display:grid;grid-template-columns:190px minmax(0,1fr);max-width:1500px;margin:auto;min-height:calc(100vh - 100px)}nav{padding:24px 14px;background:var(--paper);border-right:1px solid var(--line)}nav a{display:block;text-decoration:none;color:var(--soft);padding:12px;border-radius:7px;margin:4px 0}nav a[aria-current=page]{background:var(--active);color:var(--accent);font-weight:650}main{padding:30px;min-width:0}section{margin:16px 0}main>section{margin:0}article,.notice{background:var(--paper);border:1px solid var(--line);border-radius:12px;padding:22px;margin:16px 0}article h2{font-size:17px}.metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.metrics strong{display:block;font-size:32px}.metrics span{color:var(--soft)}.eyebrow,.tags{font-size:12px;font-weight:650;color:var(--accent);letter-spacing:.05em;margin-bottom:8px}p{margin:8px 0}pre,.path{white-space:pre-wrap;overflow-wrap:anywhere;word-break:break-word}pre{background:var(--bg);padding:12px;border-radius:6px;font:13px/1.6 monospace;max-height:480px;overflow:auto}.message{padding:16px 0;border-top:1px solid var(--line)}.message>pre{font:15px/1.7 system-ui,sans-serif;max-height:none;background:transparent;padding:0}.message>strong{text-transform:capitalize;color:var(--accent)}summary{cursor:pointer;padding:10px 0;font-weight:600}.provenance{border-top:1px solid var(--line)}input,select{font:inherit;background:var(--paper);color:var(--ink);border:1px solid var(--line);border-radius:7px;padding:10px}input{width:100%;margin:8px 0}.filters{display:flex;gap:20px;flex-wrap:wrap;margin:16px 0}.filters label{display:flex;gap:10px;align-items:center}a{color:var(--accent)}:focus-visible{outline:3px solid var(--accent);outline-offset:3px}.timeline-scroll{overflow:auto}.timeline-content table{min-width:680px}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;padding:12px;border-bottom:1px solid var(--line);vertical-align:top;overflow-wrap:anywhere}td:first-child{min-width:150px}.runner-row{display:flex;justify-content:space-between;gap:20px;padding:10px 0;border-bottom:1px solid var(--line)}footer{font-size:12px;margin-top:32px;padding-top:16px;border-top:1px solid var(--line)}[hidden]{display:none!important}
@media(prefers-color-scheme:dark){:root{--bg:#10181d;--paper:#172128;--ink:#e4eded;--soft:#a8babe;--line:#33454b;--accent:#91d9cc;--active:#263f3a}}
@media(max-width:700px){.workspace{display:block}nav{display:flex;gap:4px;flex-wrap:wrap;border-right:0;border-bottom:1px solid var(--line);padding:10px}nav a{padding:8px}main{padding:18px}header{padding:20px}.metrics{gap:8px}.metrics .notice{padding:12px}.metrics strong{font-size:26px}article,.notice{padding:16px}}
@media print{:root{--bg:white;--paper:white;--ink:black;--soft:#333;--line:#aaa;--accent:black}.workspace{display:block;min-height:0}nav,input,select,.filters,label[for],#print-section{display:none}main{padding:0}pre{max-height:none;overflow:visible}article{break-inside:auto}header{padding:10px 0}.timeline-scroll{overflow:visible}.timeline-content table{min-width:0}summary{font-size:11px;padding:2px 0}.message{padding:8px 0}.message>pre{font-size:12px;line-height:1.4}#print-scope{border-bottom:1px solid #aaa;padding-bottom:8px}}
'''
SCRIPT = r'''
(function(){
const panels=[...document.querySelectorAll('[data-panel]')];
const links=[...document.querySelectorAll('nav a')];
function navigate(focus){const requested=location.hash.slice(1);const target=panels.find(p=>p.id===requested)||panels[0];panels.forEach(p=>p.hidden=p!==target);links.forEach(a=>{if(a.hash==='#'+target.id)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(focus)target.querySelector('h2').focus();}
window.addEventListener('hashchange',()=>navigate(true));navigate(false);
function filterEvidence(){const q=document.getElementById('filter').value.toLowerCase();const runner=document.getElementById('runner-filter').value;const status=document.getElementById('status-filter').value;const cards=[...document.querySelectorAll('#evidence article')];cards.forEach(a=>a.hidden=!a.textContent.toLowerCase().includes(q)||(runner!=='all'&&a.dataset.runner!==runner)||(status!=='all'&&a.dataset.status!==status));const count=cards.filter(a=>!a.hidden).length;document.getElementById('result-count').textContent=count+' of '+cards.length+' artifacts shown';document.getElementById('no-matches').hidden=count!==0||cards.length===0;}
['filter','runner-filter','status-filter'].forEach(id=>document.getElementById(id).addEventListener(id==='filter'?'input':'change',filterEvidence));filterEvidence();
function filterTimeline(){const q=document.getElementById('timeline-search').value.toLowerCase();const picker=document.getElementById('timeline-kind');const kind=picker?picker.value:'all';const rows=[...document.querySelectorAll('[data-timeline-row]')];rows.forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(q)||(kind!=='all'&&r.dataset.kind!==kind));document.getElementById('timeline-count').textContent=rows.filter(r=>!r.hidden).length+' of '+rows.length+' displayed timeline records match';}
document.getElementById('timeline-search').addEventListener('input',filterTimeline);const picker=document.getElementById('timeline-kind');if(picker)picker.addEventListener('change',filterTimeline);filterTimeline();
const printScope=document.getElementById('print-scope');
function updatePrintScope(){const target=panels.find(p=>!p.hidden);const parts=['Print scope: '+(target?target.querySelector('h2').textContent:'visible sections')+'. Current filters and expanded details only; this is not the complete evidence export. Use report.json and timeline.json/CSV for full records.'];if(target&&target.id==='evidence'){parts.push('Search: '+(document.getElementById('filter').value||'(none)')+'; runner: '+document.getElementById('runner-filter').value+'; status: '+document.getElementById('status-filter').value+'.');}if(target&&target.id==='timeline'){parts.push('Search: '+(document.getElementById('timeline-search').value||'(none)')+'; type: '+(picker?picker.value:'all')+'.');}printScope.textContent=parts.join(' ');}
window.addEventListener('beforeprint',updatePrintScope);
document.getElementById('print-section').addEventListener('click',()=>{updatePrintScope();window.print();});
window.addEventListener('hashchange',updatePrintScope);
['filter','runner-filter','status-filter','timeline-search','timeline-kind'].forEach(id=>{const el=document.getElementById(id);if(el)el.addEventListener(el.tagName==='INPUT'?'input':'change',updatePrintScope);});updatePrintScope();
})();
'''
